{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distance for each pair
    mrd_edges = []
    for entry in distances:
        a, b, d = entry[0], entry[1], entry[2]
        mrd = max(core_distance[a], core_distance[b], d)
        # Canonicalise edge so smaller node name comes first
        if a > b:
            a, b = b, a
        mrd_edges.append((mrd, a, b))

    # Sort by mrd, then node names for determinism
    mrd_edges.sort()

    # Kruskal's MST via union-find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst = []
    for mrd, a, b in mrd_edges:
        if union(a, b):
            mst.append([a, b, mrd])
            if len(mst) == len(nodes) - 1:
                break

    # Return edges sorted by weight then node names
    mst.sort(key=lambda e: (e[2], e[0], e[1]))
    return {"mst": mst}
